<script lang="ts">
 import {onMount} from 'svelte';import {loadAttachment,type Attachment} from '../core/attachments';import type {StorageAdapter} from '../core/model';
 let {value,storage,onremove,ontext,ontranscribe,transcription=false}:{value:Attachment;storage:StorageAdapter;onremove:()=>void;ontext:(text:string)=>void;ontranscribe:()=>void;transcription?:boolean}=$props();let url=$state(''),error=$state(''),pending=$state(''),message=$state(''),playing=$state(false),time=$state(0),duration=$state(0);let audio=$state<HTMLAudioElement>()!;let element:HTMLElement,content:Blob|undefined;
 const clock=(seconds:number)=>`${Math.floor(seconds/60)}:${String(Math.floor(seconds%60)).padStart(2,'0')}`;
 function download(){const link=document.createElement('a');link.href=url;link.download=value.name;link.click();}
 async function share(){if(!content)return;try{const file=new File([content],value.name,{type:value.mime});if(navigator.canShare?.({files:[file]}))await navigator.share({title:value.name,files:[file]});else{download();message='Файл сохранён — его можно отправить из загрузок.';}}catch(e){if((e as Error).name!=='AbortError')message='Не удалось отправить. Можно сохранить файл.';}}
 async function toggle(){try{if(audio.paused)await audio.play();else audio.pause();}catch{error='Браузер не смог воспроизвести запись. Её можно сохранить и открыть другим приложением.';}}
 onMount(()=>{let alive=true,object='',loading=false;const load=()=>{if(loading)return;loading=true;void loadAttachment(storage,value).then(blob=>{if(alive){content=blob;object=URL.createObjectURL(blob);url=object;}}).catch(e=>{if(alive)error=e.message;});};const observer=new IntersectionObserver(entries=>{if(entries.some(e=>e.isIntersecting)){load();observer.disconnect();}},{rootMargin:'300px'});observer.observe(element);void storage.getSetting<{text:string}>('transcription-result:'+value.id).then(result=>{if(alive&&result?.text)pending=result.text;});return()=>{alive=false;observer.disconnect();if(object)URL.revokeObjectURL(object);};});
</script>
<figure bind:this={element} class="attachment-card"><div class="attachment-heading"><span title={value.name}>{value.name}</span><small>{(value.size/1024/1024).toFixed(1)} МБ</small>{#if url}<button type="button" aria-label={`Сохранить файл ${value.name}`} title="Сохранить файл" onclick={download}><svg viewBox="0 0 24 24"><path d="M12 3v12m-4-4 4 4 4-4M4 16v5h16v-5"/></svg></button><button type="button" aria-label={`Поделиться файлом ${value.name}`} title="Поделиться" onclick={share}><svg viewBox="0 0 24 24"><path d="M12 15V3m-4 4 4-4 4 4M7 10H4v11h16V10h-3"/></svg></button>{/if}<button type="button" aria-label={`Удалить вложение ${value.name}`} title="Удалить вложение" onclick={onremove}><svg viewBox="0 0 24 24"><path d="m6 6 12 12M18 6 6 18"/></svg></button></div>
 {#if error}<p role="alert">{error}</p>{:else if url}{#if value.mime.startsWith('image/')}<a href={url} target="_blank" rel="noreferrer"><img src={url} alt={value.name} decoding="async"/></a>{:else if value.mime.startsWith('video/')}<video src={url} controls playsinline preload="metadata"><track kind="captions"/></video>{:else}<audio bind:this={audio} src={url} preload="metadata" onplay={()=>playing=true} onpause={()=>playing=false} ontimeupdate={()=>time=audio.currentTime} onloadedmetadata={()=>duration=Number.isFinite(audio.duration)?audio.duration:0} onended={()=>{playing=false;if(!duration)duration=time;}}></audio><div class="audio-player"><button type="button" class="audio-play" aria-label={playing?'Приостановить запись':'Слушать запись'} onclick={toggle}><svg viewBox="0 0 24 24">{#if playing}<path d="M8 6v12M16 6v12"/>{:else}<path d="m9 5 10 7-10 7Z"/>{/if}</svg></button><input type="range" aria-label="Позиция в записи" min="0" max={duration||1} step=".1" value={time} disabled={!duration} oninput={event=>{audio.currentTime=Number(event.currentTarget.value);time=audio.currentTime;}}/><span>{clock(time)}{duration?` / ${clock(duration)}`:''}</span></div>{/if}{:else}<p>Открываем вложение…</p>{/if}
 {#if message}<p role="status">{message}</p>{/if}
 {#if value.mime.startsWith('audio/')&&transcription}<button type="button" class="transcribe" onclick={ontranscribe}>{value.transcript?'Распознать заново':'Расшифровать на устройстве'}</button>{/if}
 {#if value.transcript!==undefined}<label class="transcript-label">Расшифровка<textarea aria-label={`Расшифровка ${value.name}`} value={value.transcript} oninput={e=>ontext(e.currentTarget.value)} rows="5"></textarea></label>{/if}
 {#if pending&&pending!==value.transcript}<label class="transcript-label">Сохранённый результат распознавания<textarea readonly value={pending} rows="5"></textarea></label><button type="button" onclick={()=>ontext(pending)}>Использовать этот текст</button>{/if}
</figure>
<style>.attachment-card{margin:14px 0;padding:12px;border:1px solid var(--theme-border);border-radius:18px;background:var(--theme-surfaceAlt);min-width:0}.attachment-heading{display:flex;align-items:center;gap:8px;font-size:12px;margin-bottom:8px}.attachment-heading>span{flex:1;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.attachment-heading small{color:var(--theme-muted);white-space:nowrap}.attachment-heading button{display:grid;place-items:center;min-height:32px;width:32px;padding:6px;background:transparent;border:0}.attachment-heading svg{width:16px;height:16px;fill:none;stroke:currentColor;stroke-width:1.5}img,video{display:block;max-width:100%;max-height:420px;object-fit:contain;border-radius:10px;margin:auto}audio{display:none}.audio-player{display:flex;align-items:center;gap:10px;padding:6px 0}.audio-player .audio-play{display:grid;place-items:center;width:44px;min-height:44px;border:0;border-radius:50%;background:var(--theme-surface);color:var(--theme-text);flex:none}.audio-play svg{width:18px;height:18px;fill:currentColor;stroke:currentColor;stroke-width:2;stroke-linecap:round}.audio-player input{flex:1;min-width:0;padding:0;accent-color:var(--theme-accent);height:44px;min-height:44px}.audio-player>span{font-size:10px;font-variant-numeric:tabular-nums;color:var(--theme-muted);white-space:nowrap}.attachment-heading{gap:3px}.attachment-heading small{margin-inline:4px}.attachment-heading button{width:36px;min-height:40px;flex:none}.transcribe{margin-top:10px;font-size:12px;min-height:36px;padding:6px 10px;background:transparent}.transcript-label{display:flex;flex-direction:column;align-items:stretch;gap:8px;margin-top:12px;color:var(--theme-muted);font-size:12px}.transcript-label textarea{font-size:16px;line-height:1.65;min-height:140px;width:100%;resize:vertical;background:transparent;border:0;padding:0;color:var(--theme-text)}p{font-size:12px}</style>
